import { Button, Drawer, Menu, MenuItem, Divider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type SideNavProps = {
  onNavigate: (key: NavKey) => void;
};

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function SideNav({ onNavigate }: SideNavProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button
        onClick={() => setOpen(true)}
        aria-haspopup="menu"
        aria-expanded={open}
      >
        Меню
      </Button>

      <Drawer
        open={open}
        placement="left"
        onClose={() => setOpen(false)}
        aria-label="Навигация"
      >
        <Menu style={{ padding: 'var(--jx-space-2)' }}>
          {ITEMS.map((item) => (
            <MenuItem key={item.key} onSelect={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}
          <Divider />
          <MenuItem tone="danger" onSelect={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

